  1733  int usbredirparser_unserialize(struct usbredirparser *parser_pub,
  1734                                 uint8_t *state, int len)
  1735  {
  1736      struct usbredirparser_priv *parser =
  1737          (struct usbredirparser_priv *)parser_pub;
  1738      struct usbredirparser_buf *wbuf, **next;
  1739      uint32_t orig_caps[USB_REDIR_CAPS_SIZE];
  1740      uint8_t *data;
  1741      uint32_t i, l, header_len, remain = len;
  1742
  1743      if (unserialize_int(parser, &state, &remain, &i, "magic"))
  1744          return -1;
  1745      if (i != USBREDIRPARSER_SERIALIZE_MAGIC) {
  1746          ERROR("error unserialize magic mismatch");
  1747          return -1;
  1748      }
  1749
  1750      if (unserialize_int(parser, &state, &remain, &i, "length"))
  1751          return -1;
  1752      if (i != len) {
  1753          ERROR("error unserialize length mismatch");
  1754          return -1;
  1755      }
  1756
  1757      data = (uint8_t *)parser->our_caps;
  1758      i = USB_REDIR_CAPS_SIZE * sizeof(int32_t);
  1759      memcpy(orig_caps, parser->our_caps, i);
  1760      if (unserialize_data(parser, &state, &remain, &data, &i, "our_caps"))
  1761          return -1;
  1762      for (i =0; i < USB_REDIR_CAPS_SIZE; i++) {
  1763          if (parser->our_caps[i] != orig_caps[i]) {
  1764              /* orig_caps is our original settings
  1765               * parser->our_caps is off the wire.
  1766               * We want to allow reception from an older
  1767               * usbredir that doesn't have all our features.
  1768               */
  1769              if (parser->our_caps[i] & ~orig_caps[i]) {
  1770                  /* Source has a cap we don't */
  1771                  ERROR("error unserialize caps mismatch ours: %x recv: %x",
  1772                        orig_caps[i], parser->our_caps[i]);
  1773                  return -1;
  1774              } else {
  1775                  /* We've got a cap the source doesn't - that's OK */
  1776                  WARNING("unserialize missing some caps; ours: %x recv: %x",
  1777                        orig_caps[i], parser->our_caps[i]);
  1778              }
  1779          }
  1780      }
  1781
  1782      data = (uint8_t *)parser->peer_caps;
  1783      i = USB_REDIR_CAPS_SIZE * sizeof(int32_t);
  1784      if (unserialize_data(parser, &state, &remain, &data, &i, "peer_caps"))
  1785          return -1;
  1786      if (i)
  1787          parser->have_peer_caps = 1;
  1788
  1789      if (unserialize_int(parser, &state, &remain, &i, "skip"))
  1790          return -1;
  1791      parser->to_skip = i;
  1792
  1793      header_len = usbredirparser_get_header_len(parser_pub);
  1794      data = (uint8_t *)&parser->header;
  1795      i = header_len;
  1796      if (unserialize_data(parser, &state, &remain, &data, &i, "header"))
  1797          return -1;
  1798      parser->header_read = i;
  1799
  1800      /* Set various length field froms the header (if we've a header) */
  1801      if (parser->header_read == header_len) {
  1802                  int type_header_len =
  1803                      usbredirparser_get_type_header_len(parser_pub,
  1804                                                         parser->header.type, 0);
  1805                  if (type_header_len < 0 ||
  1806                      type_header_len > sizeof(parser->type_header) ||
  1807                      parser->header.length < type_header_len ||
  1808                      (parser->header.length > type_header_len &&
  1809                       !usbredirparser_expect_extra_data(parser))) {
  1810                      ERROR("error unserialize packet header invalid");
  1811                      return -1;
  1812                  }
  1813                  parser->type_header_len = type_header_len;
  1814                  parser->data_len = parser->header.length - type_header_len;
  1815      }
  1816
  1817      data = parser->type_header;
  1818      i = parser->type_header_len;
  1819      if (unserialize_data(parser, &state, &remain, &data, &i, "type_header"))
  1820          return -1;
  1821      parser->type_header_read = i;
  1822
  1823      if (parser->data_len) {
  1824          parser->data = malloc(parser->data_len);
  1825          if (!parser->data) {
  1826              ERROR("Out of memory allocating unserialize buffer");
  1827              return -1;
  1828          }
  1829      }
  1830      i = parser->data_len;
  1831      if (unserialize_data(parser, &state, &remain, &parser->data, &i, "data"))
  1832          return -1;
  1833      parser->data_read = i;
  1834
  1835      /* Get the write buffer count and the write buffers */
  1836      if (unserialize_int(parser, &state, &remain, &i, "write_buf_count"))
  1837          return -1;
  1838      next = &parser->write_buf;
  1839      while (i) {
  1840          wbuf = calloc(1, sizeof(*wbuf));
  1841          if (!wbuf) {
  1842              ERROR("Out of memory allocating unserialize buffer");
  1843              return -1;
  1844          }
  1845          *next = wbuf;
  1846          l = 0;
  1847          if (unserialize_data(parser, &state, &remain, &wbuf->buf, &l, "wbuf"))
  1848              return -1;
  1849          wbuf->len = l;
  1850          next = &wbuf->next;
  1851          i--;
  1852      }
  1853
  1854      if (remain) {
  1855          ERROR("error unserialize %d bytes of extraneous state data", remain);
  1856          return -1;
  1857      }
  1858
  1859      return 0;
  1860  }
